let project=DM.project(),library=[],libraryFonts=[],settings={theme:'dark'},selected=new Set(),page=0,history=[],future=[],saveTimer,saveSerial=Promise.resolve(),revision=0,savedRevision=0,rootPath='',ready=false,zoom=0,filter='all',drag=null,carDrag=null,lastLibrary=null,busy=false,carImportView='side';
const carData={};
const items=()=>project.items.filter(i=>selected.has(i.id));
const current=()=>items().length===1?items()[0]:null;
