 const change=fn=>{try{mutate(()=>{const live=project.items.find(x=>x.id===i.id);if(!live)throw Error('Select a decal first.');if(live.locked)throw Error('Unlock this decal before editing.');fn(live);});}catch(e){fail(e);render();}};
